/* Searchable country/city selection and explicitly requested coarse location. No geocoding API. */
const COUNTRY_CODES='AD AE AF AG AI AL AM AO AQ AR AS AT AU AW AX AZ BA BB BD BE BF BG BH BI BJ BL BM BN BO BQ BR BS BT BV BW BY BZ CA CC CD CF CG CH CI CK CL CM CN CO CR CU CV CW CX CY CZ DE DJ DK DM DO DZ EC EE EG EH ER ES ET FI FJ FK FM FO FR GA GB GD GE GF GG GH GI GL GM GN GP GQ GR GS GT GU GW GY HK HM HN HR HT HU ID IE IL IM IN IO IQ IR IS IT JE JM JO JP KE KG KH KI KM KN KP KR KW KY KZ LA LB LC LI LK LR LS LT LU LV LY MA MC MD ME MF MG MH MK ML MM MN MO MP MQ MR MS MT MU MV MW MX MY MZ NA NC NE NF NG NI NL NO NP NR NU NZ OM PA PE PF PG PH PK PL PM PN PR PS PT PW PY QA RE RO RS RU RW SA SB SC SD SE SG SH SI SJ SK SL SM SN SO SR SS ST SV SX SY SZ TC TD TF TG TH TJ TK TL TM TN TO TR TT TV TW TZ UA UG UM US UY UZ VA VC VE VG VI VN VU WF WS YE YT ZA ZM ZW'.toLowerCase().split(' ');
const COUNTRY_RU=new Intl.DisplayNames(['ru'],{type:'region'}),COUNTRY_EN=new Intl.DisplayNames(['en'],{type:'region'});
const COUNTRIES=COUNTRY_CODES.map(id=>[id,COUNTRY_RU.of(id.toUpperCase()),COUNTRY_EN.of(id.toUpperCase())]).sort((a,b)=>a[1].localeCompare(b[1],'ru'));
const PLACES=[['berlin','de','Берлин','Berlin',52.52,13.405],['hamburg','de','Гамбург','Hamburg',53.551,9.994],['munich','de','Мюнхен','Munich',48.137,11.576],['cologne','de','Кёльн','Cologne',50.938,6.96],['moscow','ru','Москва','Moscow',55.756,37.617],['spb','ru','Санкт-Петербург','Saint Petersburg',59.934,30.335],['kazan','ru','Казань','Kazan',55.797,49.108],['sochi','ru','Сочи','Sochi',43.585,39.723],['denpasar','id','Денпасар, Бали','Denpasar, Bali',-8.65,115.216],['canggu','id','Чангу, Бали','Canggu, Bali',-8.647,115.138],['ubud','id','Убуд, Бали','Ubud, Bali',-8.507,115.262],['jakarta','id','Джакарта','Jakarta',-6.208,106.846],['london','gb','Лондон','London',51.507,-.128],['manchester','gb','Манчестер','Manchester',53.48,-2.242],['nyc','us','Нью-Йорк','New York',40.713,-74.006],['la','us','Лос-Анджелес','Los Angeles',34.052,-118.244],['sf','us','Сан-Франциско','San Francisco',37.775,-122.419],['bangkok','th','Бангкок','Bangkok',13.756,100.502],['phuket','th','Пхукет','Phuket',7.881,98.392],['sydney','au','Сидней','Sydney',-33.869,151.209],['melbourne','au','Мельбурн','Melbourne',-37.814,144.963],['barcelona','es','Барселона','Barcelona',41.385,2.173],['madrid','es','Мадрид','Madrid',40.417,-3.704],['paris','fr','Париж','Paris',48.857,2.352],['lisbon','pt','Лиссабон','Lisbon',38.722,-9.139],['amsterdam','nl','Амстердам','Amsterdam',52.367,4.904],['toronto','ca','Торонто','Toronto',43.653,-79.383],['kyiv','ua','Киев','Kyiv',50.45,30.523],['tbilisi','ge','Тбилиси','Tbilisi',41.715,44.827],['istanbul','tr','Стамбул','Istanbul',41.008,28.978],['almaty','kz','Алматы','Almaty',43.239,76.89],['dubai','ae','Дубай','Dubai',25.205,55.271],['tokyo','jp','Токио','Tokyo',35.676,139.65],['singapore','sg','Сингапур','Singapore',1.352,103.82],['hanoi','vn','Ханой','Hanoi',21.028,105.834]];
for(const [id,country,ru,en,lat,lon] of PLACES)CITY[id]={ru,en,country,lat,lon};
const countryName=id=>{const c=COUNTRIES.find(x=>x[0]===id);return c?L(c[1],c[2]):'';};
const placeCaption=id=>[city(id),countryName(CITY[id]?.country)].filter(Boolean).join(' · ');
const radians=x=>x*Math.PI/180;
function distanceKm(a,b){const dlat=radians(b.lat-a.lat),dlon=radians(b.lon-a.lon),x=Math.sin(dlat/2)**2+Math.cos(radians(a.lat))*Math.cos(radians(b.lat))*Math.sin(dlon/2)**2;return 6371*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));}
// Fictional coarse points, not actual locations of people depicted in fixture images.
Object.values(PEOPLE).forEach((p,i)=>{const c=CITY[p.city];if(c?.lat!=null)p.location={lat:Math.round((c.lat+(i%4)*.02)*20)/20,lon:Math.round((c.lon+(i%3)*.025)*20)/20};});
function nearbyDistance(id){const a=S.me.location?.coords,b=person(id)?.location;return a&&b?Math.round(distanceKm(a,b)/5)*5:null;}
function cityRows(){const d=S.ui.place,q=d.q.trim().toLowerCase();const list=Object.entries(CITY).filter(([id,c])=>id!=='online'&&c.country&&(!d.country||c.country===d.country)&&(!q||(c.ru+' '+c.en+' '+id).toLowerCase().includes(q)));
 return list.slice(0,40).map(([id,c])=>`<button data-act="chooseCity" data-v="${esc(id)}">${I.pin}<span class="tx"><b>${esc(T(c))}</b><small>${esc(countryName(c.country))}</small></span>${I.chev}</button>`).join('')+(d.country&&q.length>=2&&!list.some(([,c])=>c.ru.toLowerCase()===q||c.en.toLowerCase()===q)?`<button data-act="typedCity">${I.pin}<span class="tx"><b>${L('Использовать','Use')} «${esc(d.q.trim())}»</b><small>${esc(countryName(d.country))}</small></span></button>`:'')+(!list.length&&!d.country?`<p class="note">${L('Выбери страну, чтобы указать город вручную.','Select a country to enter a city manually.')}</p>`:'');
}
function openCityPicker(current,done){S.ui.place={country:CITY[current]?.country||'',q:'',done,owner:S,route:cur()};sheet(()=>{const d=S.ui.place;return{title:L('Город','City'),body:`<label class="field"><span>${L('Страна','Country')}</span><input type="search" class="inp" data-in="countrySearch" placeholder="${L('Найти страну','Find country')}" aria-label="${L('Поиск страны','Search country')}"><select class="inp" data-ch="placeCountry" aria-label="${L('Страна','Country')}"><option value="">${L('Все страны','All countries')}</option>${COUNTRIES.map(([id,ru,en])=>`<option value="${id}" ${d.country===id?'selected':''}>${L(ru,en)}</option>`).join('')}</select></label><label class="field"><span>${L('Город','City')}</span><input type="search" class="inp" data-in="placeQuery" value="${esc(d.q)}" placeholder="${L('Начни вводить город','Start typing a city')}" aria-label="${L('Поиск города','Search city')}" autofocus></label><div class="location-results" id="placeResults">${cityRows()}</div><p class="note">${L('Если города нет в каталоге, выбери страну и введи его название.','If your city is not listed, select its country and enter the name.')}</p>`};});}
IN.countrySearch=el=>{const q=el.value.toLowerCase().trim(),select=el.parentElement.querySelector('select');for(const o of select.options)o.hidden=!!o.value&&!COUNTRIES.find(c=>c[0]===o.value)?.join(' ').toLowerCase().includes(q);};
CH.placeCountry=el=>{S.ui.place.country=el.value;$('#placeResults').innerHTML=cityRows();};
IN.placeQuery=el=>{S.ui.place.q=el.value;$('#placeResults').innerHTML=cityRows();};
function finishCity(id){const d=S.ui.place;if(S!==d.owner||cur()!==d.route)return;closeSheet();d.done(id);}
ACT.chooseCity=a=>finishCity(a.dataset.v);
ACT.typedCity=()=>{const d=S.ui.place;if(!d.country||d.q.trim().length<2)return;const id='city-'+d.country+'-'+Date.now();CITY[id]={ru:d.q.trim(),en:d.q.trim(),country:d.country};finishCity(id);};
function requestCoarseLocation(done){
 if(!navigator.geolocation){toast(L('Расположение недоступно. Выбери город вручную.','Location is unavailable. Choose a city manually.'),{type:'warn'});return;}
 const owner=S,route=cur();toast(L('Запрашиваем примерное расположение','Requesting approximate location'),{type:'info'});
 navigator.geolocation.getCurrentPosition(pos=>{if(S!==owner||cur()!==route)return;const coords={lat:Math.round(pos.coords.latitude*20)/20,lon:Math.round(pos.coords.longitude*20)/20};done(coords);},()=>{if(S===owner&&cur()===route)toast(L('Расположение не получено. Можно искать по городу.','Location was not available. You can search by city.'),{type:'warn'});},{enableHighAccuracy:false,timeout:12000,maximumAge:300000});
}
function locationFields(f,cityAct,modeAct,geoAct){const mode=f.placeMode||'city';return `<div class="sec">${L('Где искать','Where to search')}</div>${seg([['city',L('По городу','By city')],['nearby',L('Рядом','Nearby')]],mode,modeAct,'sm')}<button class="li" data-act="${cityAct}"><span class="ico">${I.pin}</span><span class="tx"><b>${f.city?esc(placeCaption(f.city)):L('Выбрать страну и город','Choose country and city')}</b><small>${L('Поиск по названию города','Search by city name')}</small></span>${I.chev}</button>${mode==='nearby'?`<p class="note mt8">${L('Только примерная область около 5 км. Точная точка и адрес не сохраняются и не показываются.','Only a coarse area of about 5 km. Your exact position and address are never stored or displayed.')}</p><button class="btn soft mt8" data-act="${geoAct}">${I.pin}${f.coords?L('Обновить примерное расположение','Update approximate location'):L('Указать примерное расположение','Set approximate location')}</button>${f.coords?`<p class="note mt8">${L('Примерная область выбрана','Approximate area is set')}</p>`:''}`:''}`;}

function nearestKnownCity(coords){const near=PLACES.map(([id,country,ru,en,lat,lon])=>({id,km:distanceKm(coords,{lat,lon})})).sort((a,b)=>a.km-b.km)[0];return near?.km<=50?near.id:'';}
